(4855137, 704105, 5354, '<td valign="top">This is my equal #1 with a score of 9.<br/>If you get to recrop this just leave a sliver more space at the bottom right, they need a little bit of space to fly into.</td>', 'This is my equal #1 with a score of 9.If you get to recrop this just leave a sliver more space at the bottom right, they need a little bit of space to fly into.', '2008-08-01 07:26:36.000000', NULL, 1),
(4855138, 705384, 5354, '<td valign="top">Wonderful, especially the swirl in the mid-ground. One of my favourites of the challenge</td>', 'Wonderful, especially the swirl in the mid-ground. One of my favourites of the challenge', '2008-08-01 07:27:19.000000', NULL, 1),
(4855139, 702618, 5354, '<td valign="top">Classic, very well executed. Shame about the boot print - hope it wasn''t yours.</td>', 'Classic, very well executed. Shame about the boot print - hope it wasn''t yours.', '2008-08-01 07:28:12.000000', NULL, 1),
(4855141, 703296, 5354, '<td valign="top">Very subtle pastel shading, very simple and elegant.</td>', 'Very subtle pastel shading, very simple and elegant.', '2008-08-01 07:28:44.000000', NULL, 1),
(4855142, 703869, 5354, '<td valign="top">Terrific foreground and lighting, unfortunately let down by a non-entity of a background - needs a lighthouse/ship/white horse galloping ...</td>', 'Terrific foreground and lighting, unfortunately let down by a non-entity of a background - needs a lighthouse/ship/white horse galloping ...', '2008-08-01 07:30:14.000000', NULL, 1),
(4855143, 702744, 3306, '<td valign="top">Lovely shot. You captured this one beautifully. The colors are incredible. The backround would look nicer if you smoothed it out with a program such as Neat Image.</td>', 'Lovely shot. You captured this one beautifully. The colors are incredible. The backround would look nicer if you smoothed it out with a program such as Neat Image.', '2008-08-01 07:30:37.000000', NULL, 1),
(4855144, 705261, 5354, '<td valign="top">Very nice indeed, one of my top scorers. Love the strong foregrouns and the way the mountain floats on the mist.</td>', 'Very nice indeed, one of my top scorers. Love the strong foregrouns and the way the mountain floats on the mist.', '2008-08-01 07:31:12.000000', NULL, 1),
