INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4865277, 695729, 24896, '<td valign="top">Awesome photo! very well edited, great detail in the Cabin and a wonderful sky. Love the bits of light coming through the roof. Lots of nice sightlines to let you read this photo. Very well done. The best I have seen so far! Best of luck. Scott</td>', 'Awesome photo! very well edited, great detail in the Cabin and a wonderful sky. Love the bits of light coming through the roof. Lots of nice sightlines to let you read this photo. Very well done. The best I have seen so far! Best of luck. Scott', '2008-08-04 19:33:10.000000', NULL, 1),
(4865285, 702472, 96805, '<td valign="top">love the coloring</td>', 'love the coloring', '2008-08-04 19:35:52.000000', NULL, 1),
(4865286, 705265, 24896, '<td valign="top">Awesome perspective! The reflections and silhouettes make it a 10. best of luck. Scott</td>', 'Awesome perspective! The reflections and silhouettes make it a 10. best of luck. Scott', '2008-08-04 19:36:20.000000', NULL, 1),
(4865298, 695356, 24896, '<td valign="top">Great exposure with backlight to boot! Excellent crop and razor sharp. A photo to be very proud of. I love that you can still see the feet through the reflection. Just perfect. I hope it scores very well for you. A 10 in my books. Best of luck. Scott</td>', 'Great exposure with backlight to boot! Excellent crop and razor sharp. A photo to be very proud of. I love that you can still see the feet through the reflection. Just perfect. I hope it scores very well for you. A 10 in my books. Best of luck. Scott', '2008-08-04 19:40:22.000000', NULL, 1),
(4865308, 703122, 92192, '<td valign="top">Excellent photo.  The eye is so sharp.  I like the black background.  I can just hear him screeching.</td>', 'Excellent photo.  The eye is so sharp.  I like the black background.  I can just hear him screeching.', '2008-08-04 19:44:34.000000', NULL, 1),
(4865309, 695854, 92192, '<td valign="top">I love the reflections.  Nice editing job.</td>', 'I love the reflections.  Nice editing job.', '2008-08-04 19:45:06.000000', NULL, 1),
(4865315, 705241, 92192, '<td valign="top">Well done.  The fluidity of the fire is perfect.  I love the light in her eye.</td>', 'Well done.  The fluidity of the fire is perfect.  I love the light in her eye.', '2008-08-04 19:48:38.000000', NULL, 1),
(4865316, 701144, 92192, '<td valign="top">Love the feather detail.</td>', 'Love the feather detail.', '2008-08-04 19:48:59.000000', NULL, 1),
(4865320, 703470, 24896, '<td valign="top">I can''t get over the crazy amount of detail in this pic. Awesome color in the sky and NOTHING looks over processed!!! Please post your setup and editing details if you haven''t already. Truly a pic to be very proud of. I hope it does very well for you. A 10 and a Fav. Scott</td>', 'I can''t get over the crazy amount of detail in this pic. Awesome color in the sky and NOTHING looks over processed!!! Please post your setup and editing details if you haven''t already. Truly a pic to be very proud of. I hope it does very well for you. A 10 and a Fav. Scott', '2008-08-04 19:50:01.000000', NULL, 1),
